/* ------------------------------------------------------------------
   TRKE — trail & city race tracker for Serbia and the region
   Seed calendar, 2026 season, transcribed from published calendars:
     RS / BA / ME  — trci.rs (dates, distances, elevation)
     SI            — hac.si running calendar (dates and places;
                     most organisers have not published courses yet)
     MK            — trci.rs, plus skopskimaraton.com.mk
     HR            — trci.rs, plus zagreb-marathon.com and utrka.com
     ME upcoming   — podgorica.run and bokamarathon.com
     2027 + fixes  — mountain-race.rs
     Ljubljana marathon date from ljubljanskimaraton.si
   gain: 0 means the organiser has published no figure. Distances are
   omitted entirely where the course is not out. Nothing is estimated.
   2027: the first confirmed dates are in, from mountain-race.rs.
   The rest of the 2027 season is not published yet.
-------------------------------------------------------------------*/

const STORE_KEY = "trke-srb:v2";
// Language lives under its own key so "Erase all" never flips the UI language.
const LANG_KEY = "trke-lang";

// Serbo-Croatian speakers get Serbian; everyone else starts in English.
function detectLang() {
  try {
    const nav = (navigator.language || "").toLowerCase();
    return /^(sr|hr|bs|sh|cnr)\b/.test(nav) ? "sr" : "en";
  } catch {
    return "sr";
  }
}

