const LangCtx = React.createContext("sr");
const useT = () => STR[useContext(LangCtx)];
const useLang = () => useContext(LangCtx);

/* ---------------------------- helpers ---------------------------- */


function parseDate(iso) {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(y, m - 1, d);
}

function fmtDate(iso, lang = "sr") {
  const d = parseDate(iso);
  return { day: String(d.getDate()).padStart(2, "0"), mon: MONTHS[lang][d.getMonth()], year: d.getFullYear() };
}

function fmtDay(isoTime, lang = "sr") {
  const d = new Date(isoTime);
  if (isNaN(d)) return "";
  return `${d.getDate()}. ${MONTHS[lang][d.getMonth()].toLowerCase()} ${d.getFullYear()}.`;
}

function daysUntil(iso) {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  return Math.round((parseDate(iso) - today) / 86400000);
}

function hash(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

// Android aplikacija (Capacitor) postavlja window.__nativeLN — lokalna obaveštenja
// koja stižu i kad je aplikacija zatvorena. U pregledaču ga nema.
function nativeLN() {
  return (typeof window !== "undefined" && window.__nativeLN) || null;
}
const lnPerm = (r) => (r && r.display === "granted" ? "granted" : r && r.display === "denied" ? "denied" : "default");

function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Deterministic ridgeline derived from the hardest distance on offer.
function ridgeline(seed, steepness, w = 220, h = 46) {
  const rand = mulberry32(hash(seed));
  const n = 26;
  const amp = Math.max(0.06, Math.min(1, steepness));
  let y = 0.5;
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const drift = (rand() - 0.48) * amp * 0.9;
    y = Math.max(0.06, Math.min(0.94, y + drift));
    const arch = Math.sin((i / n) * Math.PI) * amp * 0.28;
    pts.push([(i / n) * w, (1 - (y * 0.62 + arch)) * h]);
  }
  const line = pts.map((p, i) => `${i ? "L" : "M"}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(" ");
  return { line, area: `${line} L${w},${h} L0,${h} Z` };
}

function fmtSecs(s) {
  const hh = Math.floor(s / 3600);
  const mm = Math.floor((s % 3600) / 60);
  const ss = s % 60;
  return `${hh}:${String(mm).padStart(2, "0")}:${String(ss).padStart(2, "0")}`;
}

function pace(secs, km) {
  if (!secs || !km) return "—";
  const p = Math.round(secs / km);
  return `${Math.floor(p / 60)}:${String(p % 60).padStart(2, "0")} /km`;
}

/* --------------------------- storage ----------------------------- */

const hasStorage = () =>
  typeof window !== "undefined" && window.storage && typeof window.storage.set === "function";

// The storage wrapper can throw on a response it can't parse even when the write
// landed, so a write is only judged by reading the value back.
async function writeVerified(key, payload) {
  if (!hasStorage()) return { ok: false, reason: "errStorageNA" };
  let thrown = null;
  try {
    await window.storage.set(key, payload, false);
  } catch (e) {
    thrown = e;
  }
  try {
    const back = await window.storage.get(key, false);
    if (back && back.value === payload) return { ok: true, reason: "" };
  } catch (e) {
    if (!thrown) thrown = e;
  }
  const msg = thrown && thrown.message ? thrown.message : thrown ? String(thrown) : "errReadBack";
  return { ok: false, reason: String(msg).slice(0, 160) };
}

const EMPTY_STATE = { tracking: {}, custom: [], edits: {}, notified: {} };

async function loadState() {
  if (!hasStorage()) return EMPTY_STATE;
  try {
    const res = await window.storage.get(STORE_KEY, false);
    if (!res || !res.value) return EMPTY_STATE;
    const parsed = JSON.parse(res.value);
    return {
      tracking: parsed.tracking && typeof parsed.tracking === "object" ? parsed.tracking : {},
      custom: Array.isArray(parsed.custom) ? parsed.custom : [],
      edits: parsed.edits && typeof parsed.edits === "object" ? parsed.edits : {},
      notified: parsed.notified && typeof parsed.notified === "object" ? parsed.notified : {},
    };
  } catch {
    return EMPTY_STATE;
  }
}

// A saved correction replaces the seeded guess and retires the "nepotvrđeno" flag.
const URL_RE = /^https?:\/\/[^\s.]+\.\S+$/i;

function applyEdit(race, edit) {
  if (!edit) return race;
  return {
    ...race,
    date: edit.date || race.date,
    city: edit.city || race.city,
    distances: Array.isArray(edit.distances) && edit.distances.length ? edit.distances : race.distances,
    reg: typeof edit.reg === "string" ? edit.reg || undefined : race.reg,
    unconfirmed: false,
    edited: true,
  };
}

/* ---------------------------- UI bits ---------------------------- */

function Ridge({ seed, steepness, tone, filled }) {
  const { line, area } = useMemo(() => ridgeline(seed, steepness), [seed, steepness]);
  const gid = `g-${hash(seed)}`;
  return (
    <svg className="ridge" viewBox="0 0 220 46" preserveAspectRatio="none" aria-hidden="true">
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={tone} stopOpacity={filled ? 0.42 : 0.2} />
          <stop offset="100%" stopColor={tone} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill={`url(#${gid})`} />
      <path d={line} fill="none" stroke={tone} strokeWidth="1.6" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}

function BackToTop() {
  const t = useT();
  const [show, setShow] = useState(false);

  useEffect(() => {
    const onScroll = () => setShow(window.scrollY > 500);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const toTop = () => {
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    try {
      window.scrollTo({ top: 0, behavior: reduced ? "auto" : "smooth" });
    } catch {
      // Safari before 15.4 rejects the options object outright.
      window.scrollTo(0, 0);
    }
    if (window.scrollY > 0 && reduced) window.scrollTo(0, 0);
  };

  return (
    <button
      type="button"
      className={`to-top${show ? " to-top-on" : ""}`}
      onClick={toTop}
      tabIndex={show ? 0 : -1}
      aria-hidden={!show}
      aria-label={t.backToTop}
      title={t.backToTop}
      data-testid="to-top"
    >
      <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
        <path d="M12 19V6M12 5l-7 7M12 5l7 7" fill="none" stroke="currentColor" strokeWidth="2.2"
              strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    </button>
  );
}

function Stat({ label, value, unit }) {
  return (
    <div className="stat">
      <div className="stat-val">
        {value}
        {unit && <span className="stat-unit">{unit}</span>}
      </div>
      <div className="stat-lab">{label}</div>
    </div>
  );
}

function Chip({ active, onClick, children, testid }) {
  return (
    <button type="button" className={`chip${active ? " chip-on" : ""}`} aria-pressed={active} onClick={onClick} data-testid={testid}>
      {children}
    </button>
  );
}

/* --------------------------- race card --------------------------- */

function RaceCard({ race, entry, onSet, onClear, onResult, onEdit }) {
  const [open, setOpen] = useState(false);
  const saved = entry?.result;
  const savedIdx = saved ? Math.max(0, race.distances.findIndex((d) => d.km === saved.km)) : 0;
  const [distIdx, setDistIdx] = useState(savedIdx);
  const [hh, setHh] = useState(saved ? String(Math.floor(saved.secs / 3600)) : "");
  const [mm, setMm] = useState(saved ? String(Math.floor((saved.secs % 3600) / 60)) : "");
  const [ss, setSs] = useState(saved ? String(saved.secs % 60) : "");
  const [err, setErr] = useState("");

  const status = entry?.status || null;
  const hasDist = race.distances.length > 0;
  const hardest = hasDist ? race.distances.reduce((a, b) => (b.km > a.km ? b : a), race.distances[0]) : null;
  const steepness = hardest ? Math.min(1, hardest.gain / (hardest.km * 55)) : 0.35;
  const tone = race.type === "trail" ? "var(--ochre)" : "var(--teal)";
  const lang = useLang();
  const t = useT();
  const d = fmtDate(race.date, lang);
  const away = daysUntil(race.date);
  const done = status === "done";

  const saveResult = () => {
    const num = (v) => (v.trim() === "" ? 0 : Number(v));
    if ([hh, mm, ss].some((v) => v.trim() !== "" && !/^\d{1,2}$/.test(v.trim()))) {
      return setErr(t.errDigits);
    }
    const h = num(hh), m = num(mm), sec = num(ss);
    if (m > 59 || sec > 59) return setErr(t.errMinSec);
    const secs = h * 3600 + m * 60 + sec;
    if (secs <= 0) return setErr(t.errNoTime);
    if (secs >= 60 * 3600) return setErr(t.errTooLong);
    if (!hasDist) return setErr(t.errNoDist);
    setErr("");
    onResult(race.id, { km: race.distances[distIdx].km, gain: race.distances[distIdx].gain, secs });
    setOpen(false);
  };

  return (
    <article className={`card${done ? " card-done" : ""}`} data-testid={`race-${race.id}`}>
      <div className="card-ridge" style={{ color: tone }}>
        <Ridge seed={race.id} steepness={steepness} tone={tone} filled={done} />
      </div>

      <div className="card-date" aria-hidden="true">
        <span className="cd-day">{d.day}</span>
        <span className="cd-mon">{d.mon}</span>
        <span className="cd-yr">{d.year}</span>
      </div>

      <div className="card-body">
        <div className="card-top">
          <h3 className="card-name">{race.name}</h3>
          <span className={`tag tag-${race.type}`}>{race.type === "trail" ? t.tagTrail : t.tagCity}</span>
          {race.edited && <span className="tag tag-edt">{t.tagEdited}</span>}
          {race.unconfirmed && (
            <span className="tag tag-unc" title={t.uncTitle}>
              {t.tagUnc}
            </span>
          )}
        </div>

        <p className="card-meta">
          <span className="cc">{countryShort(countryOf(race), lang)}</span> {race.city} ·{" "}
          {away >= 0 ? <span className="away">{t.inDays(away)}</span> : <span className="away past">{t.pastRace}</span>}
        </p>

        <ul className="dists">
          {hasDist ? (
            race.distances.map((x, i) => (
              <li key={i} className="dist">
                <b>{x.km}</b> km {x.gain > 0 && <span className="gain">↑{x.gain} m</span>}
              </li>
            ))
          ) : (
            <li className="dist dist-tbd">{t.distTbd}</li>
          )}
        </ul>

        {done && entry?.result && (
          <div className="result" data-testid={`result-${race.id}`}>
            <span className="res-time">{fmtSecs(entry.result.secs)}</span>
            <span className="res-sub">
              {entry.result.km} km · {pace(entry.result.secs, entry.result.km)}
            </span>
          </div>
        )}

        <div className="actions">
          <Chip active={status === "interested"} onClick={() => onSet(race.id, "interested")} testid={`int-${race.id}`}>
            {t.chipInterested}
          </Chip>
          <Chip active={status === "registered"} onClick={() => onSet(race.id, "registered")} testid={`reg-${race.id}`}>
            {t.chipRegistered}
          </Chip>
          <Chip
            active={done}
            onClick={() => {
              if (done) onSet(race.id, "done");
              else setOpen((v) => !v);
            }}
            testid={`done-${race.id}`}
          >
            {t.chipDone}
          </Chip>
          {status && (
            <button type="button" className="link-btn" onClick={() => onClear(race.id)} data-testid={`clear-${race.id}`}>
              {t.remove}
            </button>
          )}
          <button type="button" className="link-btn" onClick={() => onEdit(race)} data-testid={`edit-${race.id}`}>
            {t.fix}
          </button>
          {race.reg && away >= 0 && (
            <a
              className="link-btn reg-link"
              href={race.reg}
              target="_blank"
              rel="noopener noreferrer"
              data-testid={`prijava-${race.id}`}
            >
              {t.signUp}
            </a>
          )}
        </div>

        {open && !done && (
          <div className="log" data-testid={`log-${race.id}`}>
            <div className="log-row">
              <label className="lab" htmlFor={`d-${race.id}`}>
                {t.leg}
              </label>
              <select id={`d-${race.id}`} className="input" value={distIdx} onChange={(e) => setDistIdx(Number(e.target.value))}>
                {race.distances.map((x, i) => (
                  <option key={i} value={i}>
                    {x.km} km · ↑{x.gain} m
                  </option>
                ))}
              </select>
            </div>
            <div className="log-row">
              <label className="lab" htmlFor={`t-${race.id}`}>
                {t.time}
              </label>
              <div className="hms">
                <input
                  id={`t-${race.id}`}
                  className="input hms-in"
                  inputMode="numeric"
                  maxLength={2}
                  placeholder="4"
                  aria-label={t.hours}
                  value={hh}
                  onChange={(e) => { setHh(e.target.value); if (err) setErr(""); }}
                  onKeyDown={(e) => e.key === "Enter" && saveResult()}
                  data-testid={`h-${race.id}`}
                />
                <span className="colon">:</span>
                <input
                  className="input hms-in"
                  inputMode="numeric"
                  maxLength={2}
                  placeholder="12"
                  aria-label={t.minutes}
                  value={mm}
                  onChange={(e) => { setMm(e.target.value); if (err) setErr(""); }}
                  onKeyDown={(e) => e.key === "Enter" && saveResult()}
                  data-testid={`m-${race.id}`}
                />
                <span className="colon">:</span>
                <input
                  className="input hms-in"
                  inputMode="numeric"
                  maxLength={2}
                  placeholder="30"
                  aria-label={t.seconds}
                  value={ss}
                  onChange={(e) => { setSs(e.target.value); if (err) setErr(""); }}
                  onKeyDown={(e) => e.key === "Enter" && saveResult()}
                  data-testid={`s-${race.id}`}
                />
                <span className="hms-hint">{t.hms}</span>
              </div>
            </div>
            {err && <p className="err" role="alert">{err}</p>}
            <div className="log-actions">
              <button type="button" className="btn btn-primary" onClick={saveResult} data-testid={`save-${race.id}`}>
                {t.saveResult}
              </button>
              <button type="button" className="btn" onClick={() => { setOpen(false); setErr(""); }}>
                {t.cancel}
              </button>
            </div>
          </div>
        )}
      </div>
    </article>
  );
}

/* ------------------------- add race dialog ----------------------- */

function EditRace({ race, hasEdit, onSave, onReset, onDelete, onClose }) {
  const t = useT();
  const [date, setDate] = useState(race.date);
  const [city, setCity] = useState(race.city === "—" ? "" : race.city);
  const [rows, setRows] = useState(race.distances.map((d) => ({ km: String(d.km), gain: String(d.gain) })));
  const [reg, setReg] = useState(race.reg || "");
  const [err, setErr] = useState("");
  const [confirm, setConfirm] = useState(false);
  const mine = String(race.id).startsWith("mine-");
  const first = useRef(null);

  useEffect(() => {
    first.current?.focus();
    const esc = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", esc);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", esc);
      document.body.style.overflow = prev;
    };
  }, [onClose]);

  const setRow = (i, key, v) => setRows(rows.map((r, j) => (i === j ? { ...r, [key]: v } : r)));
  const addRow = () => setRows([...rows, { km: "", gain: "" }]);
  const dropRow = (i) => setRows(rows.filter((_, j) => j !== i));

  const submit = () => {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return setErr(t.errDate);
    const parsed = [];
    for (const r of rows) {
      if (r.km.trim() === "" && r.gain.trim() === "") continue;
      const km = parseFloat(r.km);
      if (!(km > 0 && km <= 500)) return setErr(t.errKmAll);
      const gain = r.gain.trim() === "" ? 0 : parseInt(r.gain, 10);
      if (!(gain >= 0 && gain <= 20000)) return setErr(t.errGainAll);
      parsed.push({ km, gain });
    }
    if (!parsed.length) return setErr(t.errOneLeg);
    const link = reg.trim();
    if (link && !URL_RE.test(link)) return setErr(t.errUrl);
    parsed.sort((a, b) => b.km - a.km);
    onSave(race.id, { date, city: city.trim(), distances: parsed, reg: link });
  };

  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal" role="dialog" aria-modal="true" aria-labelledby="edit-h" data-testid="edit-dialog">
        <h2 id="edit-h" className="modal-h">{t.editTitle}</h2>
        <p className="modal-sub">{race.name}</p>

        <div className="grid2">
          <div className="fld">
            <label className="lab" htmlFor="e-date">{t.date}</label>
            <input ref={first} id="e-date" className="input" type="date" value={date} onChange={(e) => setDate(e.target.value)} data-testid="edit-date" />
          </div>
          <div className="fld">
            <label className="lab" htmlFor="e-city">{t.place}</label>
            <input id="e-city" className="input" value={city} onChange={(e) => setCity(e.target.value)} placeholder={race.city} />
          </div>
          <div className="fld fld-wide">
            <label className="lab" htmlFor="e-reg">{t.regLink}</label>
            <input id="e-reg" className="input" type="url" inputMode="url" autoComplete="off" value={reg} onChange={(e) => setReg(e.target.value)} placeholder="https://…" data-testid="edit-reg" />
          </div>
        </div>

        <div className="rows">
          <span className="lab">{t.legs}</span>
          {rows.map((r, i) => (
            <div className="row3" key={i}>
              <input className="input" inputMode="decimal" value={r.km} onChange={(e) => setRow(i, "km", e.target.value)} placeholder={t.km} aria-label={t.distAria(i + 1)} data-testid={`edit-km-${i}`} />
              <input className="input" inputMode="numeric" value={r.gain} onChange={(e) => setRow(i, "gain", e.target.value)} placeholder={t.gainM} aria-label={t.gainAria(i + 1)} />
              <button type="button" className="btn row-x" onClick={() => dropRow(i)} disabled={rows.length === 1} aria-label={t.removeLegAria(i + 1)}>×</button>
            </div>
          ))}
          <button type="button" className="link-btn" onClick={addRow} data-testid="edit-add-row">{t.addLeg}</button>
        </div>

        {err && <p className="err" role="alert" data-testid="edit-err">{err}</p>}

        {mine && (
          <div className="del-zone">
            {confirm ? (
              <>
                <span className="del-ask">{t.deleteAsk(race.name)}</span>
                <button type="button" className="btn btn-danger" onClick={() => onDelete(race.id)} data-testid="del-yes">{t.wipeYes}</button>
                <button type="button" className="btn" onClick={() => setConfirm(false)}>{t.wipeNo}</button>
              </>
            ) : (
              <button type="button" className="link-btn danger" onClick={() => setConfirm(true)} data-testid="del-race">
                {t.deleteRace}
              </button>
            )}
          </div>
        )}

        <div className="modal-actions">
          {hasEdit && (
            <button type="button" className="link-btn danger mr-auto" onClick={() => onReset(race.id)} data-testid="edit-reset">
              {t.restore}
            </button>
          )}
          <button type="button" className="btn" onClick={onClose}>{t.cancel}</button>
          <button type="button" className="btn btn-primary" onClick={submit} data-testid="edit-submit">{t.saveEdit}</button>
        </div>
      </div>
    </div>
  );
}

function Bell({ items, permission, onAsk }) {
  const t = useT();
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    if (!open) return;
    const away = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const esc = (e) => e.key === "Escape" && setOpen(false);
    document.addEventListener("mousedown", away);
    window.addEventListener("keydown", esc);
    return () => {
      document.removeEventListener("mousedown", away);
      window.removeEventListener("keydown", esc);
    };
  }, [open]);

  return (
    <div className={`bell-wrap${open ? " open" : ""}`} ref={ref}>
      <button
        type="button"
        className="bell"
        onClick={() => setOpen((v) => !v)}
        aria-label={items.length ? `${t.reminders} (${items.length})` : t.reminders}
        aria-expanded={open}
        data-testid="bell"
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path d="M18 8a6 6 0 1 0-12 0c0 6-2 7-2 7h16s-2-1-2-7M13.7 20a2 2 0 0 1-3.4 0"
                fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
        {items.length > 0 && <span className="bell-dot" data-testid="bell-count">{items.length}</span>}
      </button>

      {open && (
        <div className="bell-panel" role="dialog" aria-label={t.reminders} data-testid="bell-panel">
          <h3 className="bell-h">{t.next7}</h3>
          {items.length === 0 ? (
            <p className="bell-empty">
              {t.bellEmpty}
            </p>
          ) : (
            <ul className="bell-list">
              {items.map(({ race, days, status }) => (
                <li key={race.id} className="bell-item">
                  <span className={`bell-days${days <= 1 ? " soon" : ""}`}>
                    {days === 0 ? t.today : days === 1 ? t.tomorrow : t.inNDays(days)}
                  </span>
                  <span className="bell-name">{race.name}</span>
                  <span className="bell-city">
                    {race.city} · {status === "registered" ? t.stEntered : t.stInterested}
                  </span>
                </li>
              ))}
            </ul>
          )}
          {permission === "default" && (
            <button type="button" className="btn btn-primary bell-ask" onClick={onAsk} data-testid="bell-ask">
              {t.bellAsk}
            </button>
          )}
          <p className="bell-note">
            {permission === "granted"
              ? nativeLN() ? t.bellNative : t.bellGranted
              : t.bellDefault}
          </p>
        </div>
      )}
    </div>
  );
}

function ConfirmWipe({ count, onConfirm, onClose }) {
  const t = useT();
  const first = useRef(null);

  useEffect(() => {
    first.current?.focus();
    const esc = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", esc);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", esc);
      document.body.style.overflow = prev;
    };
  }, [onClose]);

  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal modal-sm" role="alertdialog" aria-modal="true" aria-labelledby="wipe-h" data-testid="wipe-dialog">
        <h2 id="wipe-h" className="modal-h">{t.wipeTitle}</h2>
        <p className="wipe-p">
          {count > 0
            ? t.wipeCount(count)
            : t.nothingToWipe}
        </p>
        <p className="wipe-p wipe-warn">{t.wipeWarn}</p>
        <div className="modal-actions">
          <button ref={first} type="button" className="btn" onClick={onClose} data-testid="wipe-no">{t.giveUp}</button>
          <button type="button" className="btn btn-danger" onClick={onConfirm} data-testid="wipe-yes">{t.wipeAll}</button>
        </div>
      </div>
    </div>
  );
}

function AddRace({ onAdd, onClose }) {
  const t = useT();
  const lang = useLang();
  const [f, setF] = useState({ name: "", city: "", date: "", type: "trail", country: "RS", reg: "" });
  const [rows, setRows] = useState([{ km: "", gain: "" }]);
  const [err, setErr] = useState({ field: "", row: -1, msg: "" });
  const first = useRef(null);

  useEffect(() => {
    first.current?.focus();
    const esc = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", esc);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", esc);
      document.body.style.overflow = prev;
    };
  }, [onClose]);

  const clearErr = () => setErr({ field: "", row: -1, msg: "" });
  const set = (k) => (e) => {
    setF({ ...f, [k]: e.target.value });
    if (err.field === k) clearErr();
  };
  const setRow = (i, key, v) => {
    setRows(rows.map((r, j) => (i === j ? { ...r, [key]: v } : r)));
    if (err.field === "dist") clearErr();
  };
  const addRow = () => setRows([...rows, { km: "", gain: "" }]);
  const dropRow = (i) => {
    setRows(rows.filter((_, j) => j !== i));
    if (err.field === "dist") clearErr();
  };
  const bad = (k) => (err.field === k ? " input-bad" : "");
  const badRow = (i) => (err.field === "dist" && err.row === i ? " input-bad" : "");
  const Msg = ({ k }) =>
    err.field === k ? <p className="err" role="alert" data-testid={`err-${k}`}>{err.msg}</p> : null;

  const submit = () => {
    if (!f.name.trim()) return setErr({ field: "name", row: -1, msg: t.errName });
    if (!/^\d{4}-\d{2}-\d{2}$/.test(f.date)) return setErr({ field: "date", row: -1, msg: t.errDate });
    const parsed = [];
    for (let i = 0; i < rows.length; i++) {
      const r = rows[i];
      if (r.km.trim() === "" && r.gain.trim() === "") continue;
      const km = parseFloat(r.km);
      if (!(km > 0 && km <= 500))
        return setErr({ field: "dist", row: i, msg: t.errKm(i + 1) });
      const gain = r.gain.trim() === "" ? 0 : parseInt(r.gain, 10);
      if (!(gain >= 0 && gain <= 20000))
        return setErr({ field: "dist", row: i, msg: t.errGain(i + 1) });
      parsed.push({ km, gain });
    }
    if (!parsed.length) return setErr({ field: "dist", row: 0, msg: t.errOneLeg });
    const reg = f.reg.trim();
    if (reg && !URL_RE.test(reg)) return setErr({ field: "reg", row: -1, msg: t.errUrl });
    parsed.sort((a, b) => b.km - a.km);
    onAdd({
      id: `mine-${Date.now()}`,
      name: f.name.trim(),
      city: f.city.trim() || "—",
      country: f.country,
      type: f.type,
      date: f.date,
      distances: parsed,
      ...(reg ? { reg } : {}),
    });
  };

  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal" role="dialog" aria-modal="true" aria-labelledby="add-h" data-testid="add-dialog">
        <h2 id="add-h" className="modal-h">{t.addTitle}</h2>
        <div className="grid2">
          <div className="fld fld-wide">
            <label className="lab" htmlFor="a-name">{t.name}</label>
            <input ref={first} id="a-name" className={`input${bad("name")}`} aria-invalid={err.field === "name"} value={f.name} onChange={set("name")} placeholder="Zlatarski trail" data-testid="add-name" />
            <Msg k="name" />
          </div>
          <div className="fld">
            <label className="lab" htmlFor="a-city">{t.place}</label>
            <input id="a-city" className="input" value={f.city} onChange={set("city")} placeholder="Nova Varoš" />
          </div>
          <div className="fld">
            <label className="lab" htmlFor="a-date">{t.date}</label>
            <input id="a-date" className={`input${bad("date")}`} aria-invalid={err.field === "date"} type="date" value={f.date} onChange={set("date")} data-testid="add-date" />
            <Msg k="date" />
          </div>
          <div className="fld">
            <label className="lab" htmlFor="a-type">{t.surface}</label>
            <select id="a-type" className="input" value={f.type} onChange={set("type")}>
              <option value="trail">{t.surfaceTrail}</option>
              <option value="city">{t.surfaceCity}</option>
            </select>
          </div>
          <div className="fld">
            <label className="lab" htmlFor="a-country">{t.country}</label>
            <select id="a-country" className="input" value={f.country} onChange={set("country")} data-testid="add-country">
              <optgroup label={t.region}>
                {["RS", "BA", "ME", "HR", "MK", "SI"].map((k) => (
                  <option key={k} value={k}>{countryName(k, lang)}</option>
                ))}
              </optgroup>
              <optgroup label={t.restOfEurope}>
                {Object.keys(COUNTRIES)
                  .filter((k) => !["RS", "BA", "ME", "HR", "MK", "SI"].includes(k))
                  .map((k) => [k, countryName(k, lang)])
                  .sort((a, b) => a[1].localeCompare(b[1], lang))
                  .map(([k, v]) => (
                    <option key={k} value={k}>{v}</option>
                  ))}
              </optgroup>
            </select>
          </div>
          <div className="fld fld-wide">
            <label className="lab" htmlFor="a-reg">{t.regLink}</label>
            <input id="a-reg" className={`input${bad("reg")}`} aria-invalid={err.field === "reg"} type="url" inputMode="url" autoComplete="off" value={f.reg} onChange={set("reg")} placeholder="https://…" aria-describedby="a-reg-hint" data-testid="add-reg" />
            <span id="a-reg-hint" className="hint">{t.regHint}</span>
            <Msg k="reg" />
          </div>
        </div>

        <div className="rows">
          <span className="lab">{t.legs}</span>
          {rows.map((r, i) => (
            <div className="row3" key={i}>
              <input className={`input${badRow(i)}`} inputMode="decimal" value={r.km} onChange={(e) => setRow(i, "km", e.target.value)} placeholder={t.km} aria-label={t.distAria(i + 1)} data-testid={`add-km-${i}`} />
              <input className="input" inputMode="numeric" value={r.gain} onChange={(e) => setRow(i, "gain", e.target.value)} placeholder={t.gainM} aria-label={t.gainAria(i + 1)} data-testid={`add-gain-${i}`} />
              <button type="button" className="btn row-x" onClick={() => dropRow(i)} disabled={rows.length === 1} aria-label={t.removeLegAria(i + 1)}>×</button>
            </div>
          ))}
          <button type="button" className="link-btn" onClick={addRow} data-testid="add-add-row">{t.addLeg}</button>
          <Msg k="dist" />
        </div>

        <div className="modal-actions">
          <button type="button" className="btn" onClick={onClose}>{t.cancel}</button>
          <button type="button" className="btn btn-primary" onClick={submit} data-testid="add-submit">{t.submitAdd}</button>
        </div>
      </div>
    </div>
  );
}

/* ----------------------------- app ------------------------------- */

export default function App() {
  const [lang, setLang] = useState(detectLang);
  const t = STR[lang];
  const [state, setState] = useState(EMPTY_STATE);
  const [loading, setLoading] = useState(true);
  const [saveErr, setSaveErr] = useState("");
  const [storageOff, setStorageOff] = useState(false);
  const [q, setQ] = useState("");
  const [type, setType] = useState("all");
  const [country, setCountry] = useState("all");
  const [month, setMonth] = useState("all");
  const [mine, setMine] = useState(false);
  const [interested, setInterested] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [showPast, setShowPast] = useState(false);
  const [adding, setAdding] = useState(false);
  const [editing, setEditing] = useState(null);
  const [wiping, setWiping] = useState(false);
  const [permission, setPermission] = useState(
    nativeLN() ? "default" : typeof Notification !== "undefined" ? Notification.permission : "unsupported"
  );
  const [toast, setToast] = useState("");
  const ready = useRef(false);

  useEffect(() => {
    let alive = true;
    loadState().then((s) => {
      if (!alive) return;
      setState(s);
      setLoading(false);
      ready.current = true;
    });
    return () => { alive = false; };
  }, []);

  useEffect(() => {
    if (!ready.current) return;
    let cancelled = false;
    const payload = JSON.stringify(state);

    const write = async (attempt) => {
      if (storageOff) return;
      const res = await writeVerified(STORE_KEY, payload);
      if (cancelled) return;
      if (res.ok) {
        setSaveErr("");
      } else if (attempt < 2) {
        setTimeout(() => write(attempt + 1), 700);
      } else {
        // Three verified failures mean this context truly can't persist.
        setStorageOff(true);
        setSaveErr(res.reason);
      }
    };

    // Collapse rapid edits into a single write so we never trip the rate limit.
    const saveTimer = setTimeout(() => write(0), 400);
    return () => {
      cancelled = true;
      clearTimeout(saveTimer);
    };
  }, [state, storageOff]);

  useEffect(() => {
    if (!toast) return;
    const timer = setTimeout(() => setToast(""), 2600);
    return () => clearTimeout(timer);
  }, [toast]);

  // A saved language choice beats the browser guess.
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const r = await window.storage.get(LANG_KEY);
        if (alive && r && STR[r.value]) setLang(r.value);
      } catch {
        // Nothing saved yet, or storage is off — the browser guess stands.
      }
    })();
    return () => { alive = false; };
  }, []);

  useEffect(() => {
    try { document.documentElement.lang = lang; document.title = STR[lang].appTitle; } catch {}
  }, [lang]);

  const switchLang = useCallback(() => {
    setLang((cur) => {
      const next = cur === "sr" ? "en" : "sr";
      try { window.storage.set(LANG_KEY, next).catch(() => {}); } catch {}
      return next;
    });
  }, []);

  const [calendar, setCalendar] = useState({ generated: SEED_GENERATED, races: SEED_RACES });

  useEffect(() => {
    let alive = true;
    let best = SEED_GENERATED;
    const take = (cal) => {
      if (!alive || !cal || cal.generated <= best) return false;
      best = cal.generated;
      setCalendar(cal);
      return true;
    };
    (async () => {
      try {
        const saved = await window.storage.get(REMOTE_KEY);
        take(cleanRemote(JSON.parse(saved.value)));
      } catch {}
      try {
        const ctl = typeof AbortController !== "undefined" ? new AbortController() : null;
        const timer = setTimeout(() => ctl && ctl.abort(), 10000);
        const res = await fetch(REMOTE_URL, { cache: "no-store", signal: ctl ? ctl.signal : undefined });
        clearTimeout(timer);
        if (!res.ok) return;
        const cal = cleanRemote(await res.json());
        if (take(cal)) {
          try { await window.storage.set(REMOTE_KEY, JSON.stringify(cal)); } catch {}
        }
      } catch {}
    })();
    return () => { alive = false; };
  }, []);

  const races = useMemo(
    () =>
      [...calendar.races, ...state.custom]
        .map((r) => applyEdit(r, state.edits[r.id]))
        .sort((a, b) => a.date.localeCompare(b.date)),
    [calendar, state.custom, state.edits]
  );

  const setStatus = useCallback((id, status) => {
    setState((s) => {
      const cur = s.tracking[id];
      const next = { ...s.tracking };
      if (cur?.status === status) {
        // Toggling a status off must not silently discard a finish time.
        if (cur.result) next[id] = { status: null, result: cur.result };
        else delete next[id];
      } else {
        next[id] = { ...(cur || {}), status };
      }
      return { ...s, tracking: next };
    });
  }, []);

  const clearRace = useCallback((id) => {
    setState((s) => {
      const next = { ...s.tracking };
      delete next[id];
      return { ...s, tracking: next };
    });
    setToast("toastCleared");
  }, []);

  const saveResult = useCallback((id, result) => {
    setState((s) => ({ ...s, tracking: { ...s.tracking, [id]: { status: "done", result } } }));
    setToast(["toastSaved", fmtSecs(result.secs)]);
  }, []);

  const saveEdit = useCallback((id, edit) => {
    setState((s) => ({ ...s, edits: { ...s.edits, [id]: edit } }));
    setEditing(null);
    setToast("toastFixed");
  }, []);

  const resetEdit = useCallback((id) => {
    setState((s) => {
      const next = { ...s.edits };
      delete next[id];
      return { ...s, edits: next };
    });
    setEditing(null);
    setToast("toastRestored");
  }, []);

  const addRace = useCallback((race) => {
    setState((s) => ({ ...s, custom: [...s.custom, race] }));
    setAdding(false);
    setToast("toastAdded");
  }, []);

  const deleteRace = useCallback((id) => {
    setState((s) => {
      const tracking = { ...s.tracking };
      const edits = { ...s.edits };
      delete tracking[id];
      delete edits[id];
      return { ...s, custom: s.custom.filter((r) => r.id !== id), tracking, edits };
    });
    setEditing(null);
    setToast("toastDeleted");
  }, []);

  const resetAll = useCallback(() => {
    setState(EMPTY_STATE);
    setWiping(false);
    setToast("toastWiped");
  }, []);

  const stats = useMemo(() => {
    let km = 0, gain = 0, done = 0, reg = 0;
    for (const [id, e] of Object.entries(state.tracking)) {
      if (e.status === "registered") reg++;
      if (e.status === "done" && e.result) {
        done++;
        km += e.result.km;
        gain += e.result.gain;
      } else if (e.status === "done") done++;
    }
    const upcoming = races
      .filter((r) => state.tracking[r.id]?.status === "registered" && daysUntil(r.date) >= 0)
      .sort((a, b) => a.date.localeCompare(b.date))[0];
    return { km: Math.round(km), gain, done, reg, upcoming };
  }, [state.tracking, races]);

  // „Moja sezona" prikazuje i prošle označene trke iz tekuće godine (istrčane, prijave...).
  const thisYear = String(new Date().getFullYear());
  const hidePast = useCallback(
    (r) => !showPast && daysUntil(r.date) < 0 && !(mine && state.tracking[r.id] && r.date.slice(0, 4) === thisYear),
    [showPast, mine, state.tracking, thisYear]
  );

  const monthOptions = useMemo(() => {
    const keys = new Set();
    for (const r of races) {
      if (hidePast(r)) continue;
      if (country !== "all" && countryOf(r) !== country) continue;
      keys.add(r.date.slice(0, 7));
    }
    return [...keys].sort().map((k) => {
      const [y, m] = k.split("-");
      return { key: k, label: `${MONTHS[lang][Number(m) - 1]} ${y}` };
    });
  }, [races, hidePast, country, lang]);

  useEffect(() => {
    if (month !== "all" && !monthOptions.some((o) => o.key === month)) setMonth("all");
  }, [monthOptions, month]);

  // Races you flagged that fall inside the next week.
  const reminders = useMemo(() => {
    const out = [];
    for (const race of races) {
      const status = state.tracking[race.id]?.status;
      if (status !== "interested" && status !== "registered") continue;
      const days = daysUntil(race.date);
      if (days >= 0 && days <= 7) out.push({ race, days, status });
    }
    return out.sort((a, b) => a.days - b.days);
  }, [races, state.tracking]);

  useEffect(() => {
    const ln = nativeLN();
    if (ln) ln.checkPermissions().then((r) => setPermission(lnPerm(r))).catch(() => {});
  }, []);

  const askPermission = useCallback(() => {
    const ln = nativeLN();
    if (ln) {
      ln.requestPermissions().then((r) => setPermission(lnPerm(r))).catch(() => setPermission("denied"));
      return;
    }
    if (typeof Notification === "undefined") return;
    Notification.requestPermission()
      .then(setPermission)
      .catch(() => setPermission("denied"));
  }, []);

  // Android: zakaži podsetnike unapred (9:00, nedelju dana i dan pre trke) za trke
  // označene sa „Zanima me" ili „Prijavljen". Pri svakoj promeni sve se zakazuje iznova.
  const nativePlan = useMemo(() => {
    if (!nativeLN() || permission !== "granted") return [];
    const now = Date.now();
    const out = [];
    for (const race of races) {
      const status = state.tracking[race.id]?.status;
      if (status !== "interested" && status !== "registered") continue;
      for (const before of [7, 1]) {
        const at = parseDate(race.date);
        at.setDate(at.getDate() - before);
        at.setHours(9, 0, 0, 0);
        if (at.getTime() <= now) continue;
        out.push({
          id: hash(`${race.id}|${before}`) % 2147483647,
          title: t.appTitle,
          body: `${race.name} — ${before === 1 ? t.tomorrow : t.inAWeek}, ${race.city}`,
          schedule: { at, allowWhileIdle: true },
        });
      }
    }
    return out.sort((a, b) => a.schedule.at - b.schedule.at).slice(0, 60);
  }, [races, state.tracking, permission, t]);

  useEffect(() => {
    const ln = nativeLN();
    if (!ln || permission !== "granted") return;
    ln.getPending()
      .then((p) => (p.notifications.length ? ln.cancel({ notifications: p.notifications.map((n) => ({ id: n.id })) }) : null))
      .then(() => (nativePlan.length ? ln.schedule({ notifications: nativePlan }) : null))
      .catch(() => {});
  }, [nativePlan, permission]);

  // Fire at most one system notification per race per day, and only while the app is open.
  useEffect(() => {
    if (nativeLN() || permission !== "granted" || !reminders.length) return;
    const today = new Date().toISOString().slice(0, 10);
    const fresh = reminders.filter(({ race }) => state.notified[race.id] !== today);
    if (!fresh.length) return;
    const stamped = {};
    for (const { race, days } of fresh) {
      try {
        new Notification(t.appTitle, {
          body: `${race.name} — ${days === 0 ? t.today : days === 1 ? t.tomorrow : t.inDays(days)}, ${race.city}`,
          tag: `trka-${race.id}`,
        });
        stamped[race.id] = today;
      } catch {
        // Some contexts block the constructor outright; the panel still shows everything.
      }
    }
    if (Object.keys(stamped).length) {
      setState((prev) => ({ ...prev, notified: { ...prev.notified, ...stamped } }));
    }
  }, [permission, reminders, state.notified, t]);

  const filtersOn =
    q.trim() !== "" || type !== "all" || country !== "all" || month !== "all" || mine || interested || showPast;

  const chipCount =
    (type !== "all" ? 1 : 0) + (mine ? 1 : 0) + (interested ? 1 : 0) + (showPast ? 1 : 0);

  const resetFilters = useCallback(() => {
    setQ("");
    setType("all");
    setCountry("all");
    setMonth("all");
    setMine(false);
    setInterested(false);
    setShowPast(false);
  }, []);

  const countryChips = useMemo(() => {
    // Alphabetical by the label the dropdown shows, in the current language.
    return [...new Set(races.map(countryOf))].sort((a, b) =>
      countryShort(a, lang).localeCompare(countryShort(b, lang), lang === "sr" ? "sr-Latn" : lang)
    );
  }, [races, lang]);

  useEffect(() => {
    if (country !== "all" && !countryChips.includes(country)) setCountry("all");
  }, [countryChips, country]);

  const visible = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return races.filter((r) => {
      if (hidePast(r)) return false;
      if (type !== "all" && r.type !== type) return false;
      if (country !== "all" && countryOf(r) !== country) return false;
      if (month !== "all" && r.date.slice(0, 7) !== month) return false;
      if (mine && !state.tracking[r.id]) return false;
      if (interested && state.tracking[r.id]?.status !== "interested") return false;
      if (needle && !(`${r.name} ${r.city}`.toLowerCase().includes(needle))) return false;
      return true;
    });
  }, [races, q, type, country, month, mine, interested, hidePast, state.tracking]);

  const grouped = useMemo(() => {
    const map = new Map();
    for (const r of visible) {
      const d = parseDate(r.date);
      const key = `${d.getFullYear()}-${d.getMonth()}`;
      if (!map.has(key)) map.set(key, { label: `${MONTHS[lang][d.getMonth()]} ${d.getFullYear()}`, items: [] });
      map.get(key).items.push(r);
    }
    return [...map.values()];
  }, [visible, lang]);

  return (
    <LangCtx.Provider value={lang}>
    <div className="app">
      <style>{CSS}</style>

      <header className="hero">
        <div className="hero-img" role="img" aria-label={t.heroAlt} style={{ backgroundImage: `url(${BANNER})` }} />
        <div className="hero-scrim" aria-hidden="true" />
        <button
          type="button"
          className="lang-btn"
          onClick={switchLang}
          aria-label={t.langSwitch}
          title={t.langSwitch}
          data-testid="lang-toggle"
        >
          {t.langOther}
        </button>
        <Bell items={reminders} permission={permission} onAsk={askPermission} />
        <div className="hero-inner">
          <div className="hero-lead">
            <p className="lead">
              {stats.upcoming ? (
                <>
                  {t.next} <b>{stats.upcoming.name}</b>, {stats.upcoming.city} —{" "}
                  <span className="hl">{t.inDays(daysUntil(stats.upcoming.date))}</span>.
                </>
              ) : (
                <>{t.emptyLead}</>
              )}
            </p>
            <button type="button" className="btn btn-primary add" onClick={() => setAdding(true)} data-testid="open-add">
              {t.addRace}
            </button>
          </div>

          <div className="stats" data-testid="stats">
            <Stat label={t.statDone} value={stats.done} />
            <Stat label={t.statReg} value={stats.reg} />
            <Stat label={t.statKm} value={stats.km} />
            <Stat label={t.statGain} value={stats.gain} unit="m" />
          </div>
        </div>
      </header>

      <div className="toolbar">
        <div className="tb-inner">
          <input
            className="search"
            type="search"
            placeholder={t.search}
            aria-label={t.searchAria}
            value={q}
            onChange={(e) => setQ(e.target.value)}
            data-testid="search"
          />
          <select
            className="input country-sel"
            aria-label={t.country}
            value={country}
            onChange={(e) => setCountry(e.target.value)}
            data-testid="f-country"
          >
            <option value="all">{t.allCountries}</option>
            {countryChips.map((cc) => (
              <option key={cc} value={cc}>{countryShort(cc, lang)}</option>
            ))}
          </select>
          <select
            className="input month-sel"
            aria-label={t.month}
            value={month}
            onChange={(e) => setMonth(e.target.value)}
            data-testid="f-month"
          >
            <option value="all">{t.allMonths}</option>
            {monthOptions.map((o) => (
              <option key={o.key} value={o.key}>{o.label}</option>
            ))}
          </select>
          <div className="filters-bar">
            <button
              type="button"
              className="link-btn filters-toggle"
              onClick={() => setShowFilters((v) => !v)}
              aria-expanded={showFilters}
              aria-controls="filter-chips"
              data-testid="f-toggle"
            >
              {showFilters ? "▴ " : "▾ "}{t.filters}
              {chipCount > 0 && <span className="filters-count">{chipCount}</span>}
            </button>
            {filtersOn && (
              <button type="button" className="chip chip-reset" onClick={resetFilters} data-testid="f-reset">
                {t.resetFilters}
              </button>
            )}
          </div>
          {showFilters && (
            <div className="chips" id="filter-chips">
              <Chip active={type === "all"} onClick={() => setType("all")} testid="f-all">{t.all}</Chip>
              <Chip active={type === "trail"} onClick={() => setType("trail")} testid="f-trail">{t.trail}</Chip>
              <Chip active={type === "city"} onClick={() => setType("city")} testid="f-city">{t.city}</Chip>
              <span className="sep" />
              <Chip active={mine} onClick={() => setMine((v) => !v)} testid="f-mine">{t.mine}</Chip>
              <Chip active={interested} onClick={() => setInterested((v) => !v)} testid="f-interested">{t.interested}</Chip>
              <Chip active={showPast} onClick={() => setShowPast((v) => !v)} testid="f-past">{t.past}</Chip>
            </div>
          )}
        </div>
      </div>

      {storageOff && (
        <p className="banner banner-warn" role="status" data-testid="storage-banner">
          <b>{t.storageOff}</b> {t.storageOffBody}
          {saveErr && <span className="banner-why"> ({typeof t[saveErr] === "string" ? t[saveErr] : saveErr})</span>}
        </p>
      )}

      <main className="main">
        {loading ? (
          <div className="skeletons">
            {[0, 1, 2, 3].map((i) => <div key={i} className="skel" />)}
          </div>
        ) : grouped.length === 0 ? (
          <div className="empty" data-testid="empty">
            <h2>{t.noResults}</h2>
            <p>{t.noResultsHint}</p>
            <button type="button" className="btn btn-primary" onClick={() => setAdding(true)}>+ Dodaj trku</button>
          </div>
        ) : (
          grouped.map((g) => (
            <section key={g.label} className="month">
              <h2 className="month-h">
                <span>{g.label}</span>
                <span className="month-n">{g.items.length}</span>
              </h2>
              <div className="cards">
                {g.items.map((r) => (
                  <RaceCard
                    key={r.id}
                    race={r}
                    entry={state.tracking[r.id]}
                    onSet={setStatus}
                    onClear={clearRace}
                    onResult={saveResult}
                    onEdit={setEditing}
                  />
                ))}
              </div>
            </section>
          ))
        )}
      </main>

      <div className="danger-zone">
        <div className="dz-text">
          <h2 className="dz-h">{t.wipeMine}</h2>
          <p className="dz-p">{t.wipeBody}</p>
        </div>
        <button type="button" className="btn btn-danger" onClick={() => setWiping(true)} data-testid="reset">
          {t.wipeMine}
        </button>
      </div>

      <footer className="foot">
        <div className="credit">
          <p>© {new Date().getFullYear()} {t.appTitle}. {t.credit}</p>
          {calendar.generated && (
            <p className="cal-date" data-testid="cal-date">
              {t.calUpdated} {fmtDay(calendar.generated, lang)}
            </p>
          )}
        </div>
      </footer>

      {wiping && (
        <ConfirmWipe
          count={Object.keys(state.tracking).length + state.custom.length}
          onConfirm={resetAll}
          onClose={() => setWiping(false)}
        />
      )}
      <BackToTop />
      {adding && <AddRace onAdd={addRace} onClose={() => setAdding(false)} />}
      {editing && (
        <EditRace
          race={editing}
          hasEdit={Boolean(state.edits[editing.id])}
          onSave={saveEdit}
          onReset={resetEdit}
          onDelete={deleteRace}
          onClose={() => setEditing(null)}
        />
      )}
      {toast && (
        <div className="toast" role="status" data-testid="toast">
          {Array.isArray(toast) ? t[toast[0]](toast[1]) : t[toast] || toast}
        </div>
      )}
    </div>
    </LangCtx.Provider>
  );
}

/* ----------------------------- styles ---------------------------- */

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=Karla:wght@400;500;700&family=JetBrains+Mono:wght@400;600&display=swap');

.app {
  --slate: #16202B;
  --panel: #1E2B38;
  --panel-2: #24333F;
  --contour: #31465A;
  --snow: #E9F0F5;
  --muted: #90A6B8;
  --ochre: #E0A63C;
  --teal: #46B6A6;
  --crimson: #D6465F;

  --disp: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --body: 'Karla', system-ui, sans-serif;
  --mono: 'JetBrains Mono', ui-monospace, monospace;

  background: var(--slate);
  color: var(--snow);
  font-family: var(--body);
  min-height: 100vh;
  min-height: 100dvh;
  -webkit-font-smoothing: antialiased;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  -webkit-tap-highlight-color: transparent;
}
.app *, .app *::before, .app *::after { box-sizing: border-box; }
.app h1, .app h2, .app h3, .app p, .app ul { margin: 0; }
.app ul { list-style: none; padding: 0; }
.app a { color: var(--teal); }
.app :focus-visible { outline: 2px solid var(--ochre); outline-offset: 2px; border-radius: 3px; }

/* hero — contour map ground */
.hero {
  position: relative;
  border-bottom: 1px solid var(--contour);
  background: var(--slate);
}
.hero-img {
  height: 158px;
  background-size: cover;
  background-position: left center;
  background-repeat: no-repeat;
}
.hero-scrim {
  position: absolute; top: 0; left: 0; right: 0; height: 158px;
  background: linear-gradient(180deg, rgba(15,23,31,.05) 0%, rgba(22,32,43,.55) 62%, var(--slate) 100%);
  pointer-events: none;
}
.lang-btn {
  position: absolute; top: 14px; right: 64px; right: calc(max(14px, env(safe-area-inset-right)) + 50px); z-index: 12;
  height: 42px; min-width: 42px; padding: 0 10px; border-radius: 999px;
  background: rgba(22,32,43,.72); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
  border: 1px solid var(--contour); color: var(--snow); cursor: pointer;
  font-family: var(--mono); font-size: 12px; letter-spacing: .08em;
}
.lang-btn:hover { border-color: var(--ochre); color: var(--ochre); }
.lang-btn:focus-visible { outline: 2px solid var(--ochre); outline-offset: 2px; }
.bell-wrap { position: absolute; top: 14px; right: 14px; right: max(14px, env(safe-area-inset-right)); z-index: 12; }
.bell-wrap.open { z-index: 30; }
.bell {
  width: 42px; height: 42px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  background: rgba(22,32,43,.72); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
  border: 1px solid var(--contour); color: var(--snow); cursor: pointer; position: relative;
  -webkit-appearance: none; appearance: none; touch-action: manipulation; transition: background .16s ease;
}
.bell:hover { background: rgba(36,51,63,.9); }
.bell-dot {
  position: absolute; top: -3px; right: -3px; min-width: 19px; height: 19px; padding: 0 5px;
  border-radius: 999px; background: var(--crimson); color: #fff;
  font-family: var(--mono); font-size: 10.5px; font-weight: 600;
  display: flex; align-items: center; justify-content: center; border: 2px solid var(--slate);
}
.bell-panel {
  position: absolute; top: 50px; right: 0; width: 290px; max-width: calc(100vw - 28px);
  background: var(--panel); border: 1px solid var(--contour); border-radius: 12px; padding: 14px;
  box-shadow: 0 14px 40px rgba(0,0,0,.5); animation: rise .18s ease;
  max-height: calc(100vh - 90px - var(--ad-h, 0px)); max-height: calc(100dvh - 90px - var(--ad-h, 0px));
  overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch;
}
.bell-h { font-family: var(--disp); font-size: 18px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; margin-bottom: 10px; }
.bell-empty { font-size: 13px; color: var(--muted); line-height: 1.55; }
.bell-list { display: grid; gap: 9px; }
.bell-item { display: grid; gap: 2px; padding-left: 10px; border-left: 2px solid var(--ochre); }
.bell-days { font-family: var(--mono); font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--ochre); }
.bell-days.soon { color: #FF9FB0; }
.bell-name { font-size: 14px; font-weight: 700; }
.bell-city { font-size: 12px; color: var(--muted); }
.bell-ask { margin-top: 12px; width: 100%; }
.bell-note { font-size: 11.5px; color: var(--muted); line-height: 1.5; margin-top: 10px; }
.hero-inner { position: relative; max-width: 1080px; margin: 0 auto; padding: 0 18px 14px; margin-top: -44px; }
.hero-lead { margin-top: 10px; display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.hero-lead .add { flex: none; }
.lead { flex: 1 1 320px; text-shadow: 0 1px 12px rgba(10,16,22,.9); max-width: 56ch; font-size: 15.5px; line-height: 1.5; color: #C5D5E1; }
.lead b { color: var(--snow); }
.hl { color: var(--ochre); font-family: var(--mono); font-size: 14px; }

.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 9px; margin-top: 12px; }
.stat { background: rgba(22,32,43,.66); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); border: 1px solid var(--contour); border-radius: 10px; padding: 8px 11px; }
.stat-val { font-family: var(--disp); font-size: 26px; font-weight: 600; line-height: 1; color: var(--ochre); }
.stat-unit { font-size: 14px; margin-left: 2px; color: var(--muted); }
.stat-lab { font-family: var(--mono); font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); margin-top: 3px; }

/* toolbar */
.toolbar { position: -webkit-sticky; position: sticky; top: 0; z-index: 20; background: rgba(22,32,43,.94); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); border-bottom: 1px solid var(--contour); }
.tb-inner { max-width: 1080px; margin: 0 auto; padding: 10px 18px; display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.search {
  flex: 1 1 220px; min-width: 160px; background: var(--panel); border: 1px solid var(--contour);
  color: var(--snow); border-radius: 8px; padding: 9px 12px; font-family: var(--body); font-size: 14px;
}
.search::placeholder { color: #6E8598; }
.chips { display: flex; gap: 5px; align-items: center; flex-wrap: wrap; }
.filters-bar { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.filters-toggle { display: inline-flex; align-items: center; gap: 6px; letter-spacing: .06em; text-transform: uppercase; }
.filters-toggle[aria-expanded="true"] { color: var(--snow); }
.filters-count {
  font-family: var(--mono); font-size: 10px; line-height: 1;
  min-width: 16px; padding: 3px 4px; border-radius: 999px; text-align: center;
  background: var(--ochre); color: var(--slate);
}
.sep { width: 1px; height: 16px; background: var(--contour); margin: 0 3px; }
.country-sel, .month-sel { width: auto; flex: 0 0 auto; padding: 7px 9px; font-size: 13px; }
.chip {
  font-family: var(--mono); font-size: 11px; letter-spacing: 0;
  background: transparent; color: var(--muted); border: 1px solid var(--contour);
  padding: 5px 10px; border-radius: 999px; cursor: pointer; white-space: nowrap;
  transition: background .16s ease, color .16s ease, border-color .16s ease, transform .12s ease;
}
.chip:hover { color: var(--snow); border-color: #47637C; }
.chip:active { transform: scale(.96); }
.chip-reset { border-color: rgba(214,70,95,.5); color: #FF9FB0; }
.chip-reset:hover { border-color: var(--crimson); color: #FFC2CC; }
.chip-on { background: var(--ochre); border-color: var(--ochre); color: #1B1405; font-weight: 600; }
.input {
  background: var(--panel); border: 1px solid var(--contour); color: var(--snow);
  border-radius: 8px; padding: 9px 10px; font-family: var(--body); font-size: 14px; width: 100%;
  -webkit-appearance: none; appearance: none; min-height: 40px;
}
select.input {
  padding-right: 30px;
  background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%);
  background-position: calc(100% - 17px) 50%, calc(100% - 12px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}
.search { -webkit-appearance: none; appearance: none; }
input[type="date"].input { min-height: 42px; line-height: 1.2; }
input[type="date"]::-webkit-date-and-time-value { text-align: left; }
.btn, .chip { -webkit-appearance: none; appearance: none; touch-action: manipulation; }
.btn {
  font-family: var(--body); font-weight: 500; font-size: 13.5px; cursor: pointer;
  background: var(--panel-2); color: var(--snow); border: 1px solid var(--contour);
  padding: 9px 14px; border-radius: 8px; transition: background .16s ease, transform .12s ease;
}
.btn:hover { background: #2C3E4E; }
.btn:active { transform: scale(.97); }
.btn-primary { background: var(--ochre); color: #1B1405; border-color: var(--ochre); font-weight: 700; }
.btn-primary:hover { background: #EEB349; }
.link-btn { background: none; border: 1px solid transparent; color: var(--muted); font-family: var(--mono); font-size: 11.5px; line-height: 1; cursor: pointer; padding: 6px 8px; text-decoration: none; }
.link-btn:hover { color: var(--snow); }
.link-btn.danger:hover { color: var(--crimson); }
.reg-link { color: var(--teal); text-decoration: none; }
.reg-link:hover { color: var(--snow); text-decoration: underline; }

.btn:disabled { opacity: .4; cursor: not-allowed; }
.banner-why { font-family: var(--mono); font-size: 11px; opacity: .7; }
.banner { max-width: 1080px; margin: 12px auto 0; padding: 10px 14px; background: rgba(214,70,95,.14); border: 1px solid var(--crimson); border-radius: 8px; font-size: 13.5px; }
.banner-warn { background: rgba(224,166,60,.12); border-color: rgba(224,166,60,.45); color: #F0D9A8; }

/* list */
.main { max-width: 1080px; margin: 0 auto; padding: 14px 18px 40px; }
.month { margin-bottom: 26px; }
.month-h {
  display: flex; align-items: center; gap: 12px; margin-bottom: 12px;
  font-family: var(--disp); font-size: 22px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: #A8BECE;
}
.month-h::after { content: ""; flex: 1; height: 1px; background: var(--contour); }
.month-n { order: 3; font-family: var(--mono); font-size: 11px; color: var(--muted); }
.cards { display: grid; gap: 14px; }

.card {
  position: relative; overflow: hidden;
  display: grid; grid-template-columns: 60px 1fr; gap: 18px;
  background: var(--panel); border: 1px solid var(--contour); border-radius: 12px;
  padding: 16px 18px 22px 14px;
  transition: border-color .2s ease, transform .2s ease, background .2s ease;
}
.card:hover { border-color: #46637E; transform: translateY(-1px); }
.card-done { background: linear-gradient(90deg, rgba(70,182,166,.09), var(--panel) 45%); border-color: rgba(70,182,166,.45); }
.card-ridge { position: absolute; inset: auto 0 0 0; height: 42px; opacity: .32; pointer-events: none; }
.ridge { width: 100%; height: 100%; display: block; }

.card-date { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; border-right: 1px solid var(--contour); padding: 2px 12px 2px 2px; }
.cd-day { font-family: var(--disp); font-size: 34px; font-weight: 700; line-height: .95; color: var(--snow); }
.cd-mon { margin-top: 3px; font-family: var(--mono); font-size: 11px; text-transform: uppercase; color: var(--ochre); letter-spacing: .08em; }
.cd-yr { font-family: var(--mono); font-size: 9.5px; color: var(--muted); margin-top: 2px; }

.card-body { position: relative; min-width: 0; }
.card-top { display: flex; align-items: center; column-gap: 9px; row-gap: 6px; flex-wrap: wrap; }
.card-name { font-family: var(--disp); font-size: 24px; font-weight: 600; letter-spacing: .01em; line-height: 1.25; padding-right: 2px; }
.dist-tbd { color: var(--muted); font-style: italic; }
.tag { font-family: var(--mono); font-size: 9.5px; letter-spacing: .1em; text-transform: uppercase; padding: 3px 7px; border-radius: 4px; border: 1px solid transparent; white-space: nowrap; line-height: 1.35; }
.tag-trail { background: rgba(224,166,60,.16); color: var(--ochre); }
.tag-city { background: rgba(70,182,166,.16); color: var(--teal); }
.tag-edt { background: rgba(70,182,166,.16); color: var(--teal); border: 1px solid rgba(70,182,166,.35); }
.tag-unc { background: rgba(214,70,95,.14); color: #FF9FB0; border: 1px solid rgba(214,70,95,.35); cursor: help; }
.card-meta { font-size: 13px; color: var(--muted); margin-top: 6px; line-height: 1.75; }
.cc { display: inline-block; vertical-align: 1px; font-family: var(--mono); font-size: 9.5px; letter-spacing: .09em; text-transform: uppercase; color: #B7C9D6; background: rgba(255,255,255,.06); border: 1px solid var(--contour); border-radius: 4px; padding: 1px 6px; margin-right: 5px; }
.away { font-family: var(--mono); font-size: 12px; color: #B7C9D6; }
.away.past { color: #6E8598; }

.dists { display: flex; column-gap: 8px; row-gap: 7px; flex-wrap: wrap; margin-top: 12px; }
.dist { font-family: var(--mono); font-size: 12px; line-height: 1.4; color: #C5D5E1; background: rgba(255,255,255,.04); border: 1px solid var(--contour); border-radius: 6px; padding: 5px 9px; white-space: nowrap; }
.dist b { color: var(--snow); font-weight: 600; }
.gain { color: var(--muted); }

.result { display: flex; align-items: baseline; gap: 4px 10px; flex-wrap: wrap; margin-top: 12px; padding: 8px 10px; border-left: 3px solid var(--teal); background: rgba(70,182,166,.08); border-radius: 0 6px 6px 0; }
.res-time { font-family: var(--disp); font-size: 26px; font-weight: 700; color: var(--teal); line-height: 1; }
.res-sub { font-family: var(--mono); font-size: 11.5px; color: var(--muted); }

.actions { display: flex; column-gap: 7px; row-gap: 8px; flex-wrap: wrap; align-items: center; margin-top: 16px; }

.log { margin-top: 12px; padding: 12px; background: var(--panel-2); border: 1px solid var(--contour); border-radius: 9px; display: grid; gap: 9px; }
.log-row { display: grid; grid-template-columns: 76px 1fr; align-items: center; gap: 10px; }
.lab { font-family: var(--mono); font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.hms { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.hms-in { width: 62px; text-align: center; font-family: var(--mono); font-size: 16px; padding: 9px 4px; }
.colon { font-family: var(--mono); font-size: 17px; color: var(--muted); }
.hms-hint { font-family: var(--mono); font-size: 10px; letter-spacing: .12em; color: var(--muted); margin-left: 4px; }
.log-actions { display: flex; gap: 8px; margin-top: 2px; }
.input-bad { border-color: var(--crimson); }
.err { color: #FF8FA3; font-size: 12.5px; font-family: var(--mono); }

/* empty + skeleton */
.empty { text-align: center; padding: 56px 20px; border: 1px dashed var(--contour); border-radius: 12px; }
.empty h2 { font-family: var(--disp); font-size: 26px; font-weight: 600; }
.empty p { color: var(--muted); font-size: 14px; margin: 8px 0 18px; }
.skeletons { display: grid; gap: 12px; }
.skel { height: 118px; border-radius: 12px; background: linear-gradient(90deg, var(--panel), var(--panel-2), var(--panel)); background-size: 200% 100%; animation: sweep 1.3s linear infinite; }
@keyframes sweep { to { background-position: -200% 0; } }

/* modal */
.overlay { position: fixed; top: 0; right: 0; bottom: 0; left: 0; background: rgba(10,16,22,.72); -webkit-backdrop-filter: blur(3px); backdrop-filter: blur(3px); display: flex; align-items: center; justify-content: center; padding: 16px; z-index: 50; animation: fade .18s ease; }
@keyframes fade { from { opacity: 0; } }
.modal { width: 100%; max-width: 520px; background: var(--panel); border: 1px solid var(--contour); border-radius: 14px; padding: 20px; animation: rise .22s cubic-bezier(.2,.8,.3,1); max-height: 90vh; max-height: 90dvh; overflow-y: auto; -webkit-overflow-scrolling: touch; overscroll-behavior: contain; }
@keyframes rise { from { opacity: 0; transform: translateY(14px); } }
.modal-sm { max-width: 400px; }
.wipe-p { font-size: 14px; line-height: 1.55; color: #C5D5E1; margin-bottom: 8px; }
.wipe-warn { color: #FFB3C0; font-size: 13px; }
.modal-sub { font-family: var(--mono); font-size: 12px; color: var(--muted); margin: -8px 0 14px; }
.rows { display: grid; gap: 7px; margin-top: 13px; }
.row3 { display: grid; grid-template-columns: 1fr 1fr 38px; gap: 7px; }
.row-x { padding: 0; font-size: 18px; line-height: 1; color: var(--muted); }
.row-x:disabled { opacity: .35; cursor: not-allowed; }
.mr-auto { margin-right: auto; }
.del-zone { margin-top: 16px; padding-top: 13px; border-top: 1px solid var(--contour); display: flex; align-items: center; gap: 9px; flex-wrap: wrap; }
.del-ask { font-size: 13px; color: #FFB3C0; margin-right: auto; }
.modal-h { font-family: var(--disp); font-size: 26px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; margin-bottom: 14px; }
.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 11px; }
.fld { display: grid; gap: 5px; }
.fld-wide { grid-column: 1 / -1; }
.cal-date { font-size: 11.5px; color: var(--muted); margin-top: 4px; }
.hint { font-size: 12px; color: var(--muted); }
.modal-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

/* Android: baner (AdMob) na dnu ekrana postavlja --ad-h na svoju visinu. */
.app::after { content: ""; display: block; height: var(--ad-h, 0px); }
.to-top, .toast { margin-bottom: var(--ad-h, 0px); }
.overlay { bottom: var(--ad-h, 0px) !important; }
.to-top {
  position: fixed; right: 16px; bottom: 16px;
  right: max(16px, env(safe-area-inset-right));
  bottom: max(16px, calc(16px + env(safe-area-inset-bottom)));
  width: 46px; height: 46px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: var(--ochre); color: #1B1405; border: 0; cursor: pointer;
  box-shadow: 0 6px 22px rgba(0,0,0,.45);
  opacity: 0; transform: translateY(12px) scale(.9); pointer-events: none;
  transition: opacity .22s ease, transform .22s cubic-bezier(.2,.8,.3,1), background .16s ease;
  z-index: 40; -webkit-appearance: none; appearance: none; touch-action: manipulation;
}
.to-top-on { opacity: 1; transform: none; pointer-events: auto; }
.to-top:hover { background: #EEB349; }
.to-top:active { transform: scale(.93); }
.toast { position: fixed; left: 50%; bottom: 22px; max-width: calc(100vw - 100px); transform: translateX(-50%); background: var(--panel-2); border: 1px solid var(--contour); color: var(--snow); padding: 10px 16px; border-radius: 999px; font-size: 13.5px; z-index: 60; animation: rise .2s ease; box-shadow: 0 8px 30px rgba(0,0,0,.4); }

.danger-zone {
  max-width: 1080px; margin: 0 auto 4px; padding: 16px 18px;
  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  border: 1px solid rgba(214,70,95,.4); border-radius: 12px;
  background: rgba(214,70,95,.07);
}
.dz-h { font-family: var(--disp); font-size: 21px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: #FFB3C0; }
.dz-p { font-size: 13px; color: var(--muted); margin-top: 3px; }
.btn-danger { background: var(--crimson); border-color: var(--crimson); color: #FFF1F4; font-weight: 700; }
.btn-danger:hover { background: #E8546F; }

.foot { max-width: 1080px; margin: 0 auto; padding: 20px 18px 40px; border-top: 1px solid var(--contour); display: flex; justify-content: space-between; align-items: center; gap: 14px; flex-wrap: wrap; }
.foot p { font-size: 12.5px; color: var(--muted); max-width: 62ch; line-height: 1.5; }
.credit { display: grid; gap: 4px; }

@supports (padding: max(0px)) {
  .hero-inner, .tb-inner, .main, .foot, .danger-zone {
    padding-left: max(18px, env(safe-area-inset-left));
    padding-right: max(18px, env(safe-area-inset-right));
  }
  .foot { padding-bottom: max(40px, calc(24px + env(safe-area-inset-bottom))); }
}

@media (max-width: 620px) {
  .input, .search, select.input, textarea.input { font-size: 16px; }
  .hero-img, .hero-scrim { height: 116px; }
  .hero-inner { margin-top: -34px; padding-bottom: 11px; }
  .hero-lead .add { flex: 1 1 100%; }
  .danger-zone { flex-direction: column; align-items: stretch; }
  .danger-zone .btn { width: 100%; }

          .stats { grid-template-columns: repeat(2, 1fr); }
  .card { grid-template-columns: 46px 1fr; gap: 13px; padding: 14px 14px 20px 11px; }
  .card-date { padding-right: 9px; }
  .card-name { font-size: 20px; }
  .cd-day { font-size: 28px; }
  .card-name { font-size: 21px; }
  .grid2 { grid-template-columns: 1fr; }
  .tb-inner { padding: 10px 14px; }
  .search { flex: 1 1 100%; }
  .country-sel, .month-sel { flex: 1 1 calc(50% - 4px); width: auto; min-width: 0; }
  .chips { gap: 5px; row-gap: 6px; }
  .log-row { grid-template-columns: 1fr; gap: 4px; }
}

@media (prefers-reduced-motion: reduce) {
  .app *, .app *::before, .app *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}
`;
